def kind_from_template(apps, schema_editor):
    """Documents made before this step take their kind from their template."""
    Envelope = apps.get_model('esign', 'Envelope')
    for e in Envelope.objects.filter(template_version__isnull=False).select_related('template_version__template'):
        e.kind = e.template_version.template.kind
        e.save(update_fields=['kind'])


